1  import type {StackScreenProps} from '@react-navigation/stack';
     2  import React, {useCallback, useEffect, useMemo, useRef, useState} from 'react';
     3  import type {SectionListData} from 'react-native';
     4  import {useOnyx, withOnyx} from 'react-native-onyx';
     5  import type {OnyxEntry} from 'react-native-onyx';
     6  import FormAlertWithSubmitButton from '@components/FormAlertWithSubmitButton';
     7  import HeaderWithBackButton from '@components/HeaderWithBackButton';
     8  import {useOptionsList} from '@components/OptionListContextProvider';
     9  import ScreenWrapper from '@components/ScreenWrapper';
    10  import SelectionList from '@components/SelectionList';
    11  import InviteMemberListItem from '@components/SelectionList/InviteMemberListItem';
    12  import type {Section} from '@components/SelectionList/types';
    13  import withNavigationTransitionEnd from '@components/withNavigationTransitionEnd';
    14  import type {WithNavigationTransitionEndProps} from '@components/withNavigationTransitionEnd';
    15  import useDebouncedState from '@hooks/useDebouncedState';
    16  import useLocalize from '@hooks/useLocalize';
    17  import useNetwork from '@hooks/useNetwork';
    18  import useThemeStyles from '@hooks/useThemeStyles';
    19  import * as ReportActions from '@libs/actions/Report';
    20  import {READ_COMMANDS} from '@libs/API/types';
    21  import * as DeviceCapabilities from '@libs/DeviceCapabilities';
    22  import HttpUtils from '@libs/HttpUtils';
    23  import * as LoginUtils from '@libs/LoginUtils';
    24  import Navigation from '@libs/Navigation/Navigation';
    25  import * as OptionsListUtils from '@libs/OptionsListUtils';
    26  import type {MemberForList} from '@libs/OptionsListUtils';
    27  import * as PhoneNumber from '@libs/PhoneNumber';
    28  import * as PolicyUtils from '@libs/PolicyUtils';
    29  import type {OptionData} from '@libs/ReportUtils';
    30  import type {SettingsNavigatorParamList} from '@navigation/types';
    31  import * as Member from '@userActions/Policy/Member';
    32  import * as Policy from '@userActions/Policy/Policy';
    33  import CONST from '@src/CONST';
    34  import ONYXKEYS from '@src/ONYXKEYS';
    35  import ROUTES from '@src/ROUTES';
    36  import type SCREENS from '@src/SCREENS';
    37  import type {Beta, InvitedEmailsToAccountIDs} from '@src/types/onyx';
    38  import type {Errors} from '@src/types/onyx/OnyxCommon';
    39  import {isEmptyObject} from '@src/types/utils/EmptyObject';
    40  import AccessOrNotFoundWrapper from './AccessOrNotFoundWrapper';
    41  import withPolicyAndFullscreenLoading from './withPolicyAndFullscreenLoading';
    42  import type {WithPolicyAndFullscreenLoadingProps} from './withPolicyAndFullscreenLoading';
    43
    44  type MembersSection = SectionListData<MemberForList, Section<MemberForList>>;
    45
    46  type WorkspaceInvitePageOnyxProps = {
    47      /** Beta features list */
    48      betas: OnyxEntry<Beta[]>;
    49
    50      /** An object containing the accountID for every invited user email */
    51      invitedEmailsToAccountIDsDraft: OnyxEntry<InvitedEmailsToAccountIDs>;
    52  };
    53
    54  type WorkspaceInvitePageProps = WithPolicyAndFullscreenLoadingProps &
    55      WithNavigationTransitionEndProps &
    56      WorkspaceInvitePageOnyxProps &
    57      StackScreenProps<SettingsNavigatorParamList, typeof SCREENS.WORKSPACE.INVITE>;
    58
    59  function WorkspaceInvitePage({route, betas, invitedEmailsToAccountIDsDraft, policy}: WorkspaceInvitePageProps) {
    60      const styles = useThemeStyles();
    61      const {translate} = useLocalize();
    62      const [searchTerm, debouncedSearchTerm, setSearchTerm] = useDebouncedState('');
    63      const [selectedOptions, setSelectedOptions] = useState<MemberForList[]>([]);
    64      const [personalDetails, setPersonalDetails] = useState<OptionData[]>([]);
    65      const [usersToInvite, setUsersToInvite] = useState<OptionData[]>([]);
    66      const [didScreenTransitionEnd, setDidScreenTransitionEnd] = useState(false);
    67      const [isSearchingForReports] = useOnyx(ONYXKEYS.IS_SEARCHING_FOR_REPORTS, {initWithStoredValues: false});
    68      const firstRenderRef = useRef(true);
    69
    70      const openWorkspaceInvitePage = () => {
    71          const policyMemberEmailsToAccountIDs = PolicyUtils.getMemberAccountIDsForWorkspace(policy?.employeeList);
    72          Policy.openWorkspaceInvitePage(route.params.policyID, Object.keys(policyMemberEmailsToAccountIDs));
    73      };
    74      const {options, areOptionsInitialized} = useOptionsList({
    75          shouldInitialize: didScreenTransitionEnd,
    76      });
    77
    78      useEffect(() => {
    79          return () => {
    80              Member.setWorkspaceInviteMembersDraft(route.params.policyID, {});
    81          };
    82          // eslint-disable-next-line react-compiler/react-compiler, react-hooks/exhaustive-deps
    83      }, [route.params.policyID]);
    84
    85      useEffect(() => {
    86          Policy.clearErrors(route.params.policyID);
    87          openWorkspaceInvitePage();
    88          // eslint-disable-next-line react-compiler/react-compiler, react-hooks/exhaustive-deps -- policyID changes remount the component
    89      }, []);
    90
    91      useNetwork({onReconnect: openWorkspaceInvitePage});
    92
    93      const excludedUsers = useMemo(() => PolicyUtils.getIneligibleInvitees(policy?.employeeList), [policy?.employeeList]);
    94
    95      const defaultOptions = useMemo(() => {
    96          if (!areOptionsInitialized) {
    97              return {recentReports: [], personalDetails: [], userToInvite: null, currentUserOption: null, categoryOptions: [], tagOptions: [], taxRatesOptions: []};
    98          }
    99
   100          const inviteOptions = OptionsListUtils.getMemberInviteOptions(options.personalDetails, betas ?? [], '', excludedUsers, true);
   101
   102          return {...inviteOptions, recentReports: [], currentUserOption: null, categoryOptions: [], tagOptions: [], taxRatesOptions: []};
   103      }, [areOptionsInitialized, betas, excludedUsers, options.personalDetails]);
   104
   105      const inviteOptions = useMemo(
   106          () => OptionsListUtils.filterOptions(defaultOptions, debouncedSearchTerm, {excludeLogins: excludedUsers}),
   107          [debouncedSearchTerm, defaultOptions, excludedUsers],
   108      );
   109
   110      useEffect(() => {
   111          if (!areOptionsInitialized) {
   112              return;
   113          }
   114
   115          const newUsersToInviteDict: Record<number, OptionData> = {};
   116          const newPersonalDetailsDict: Record<number, OptionData> = {};
   117          const newSelectedOptionsDict: Record<number, MemberForList> = {};
   118
   119          // Update selectedOptions with the latest personalDetails and policyEmployeeList information
   120          const detailsMap: Record<string, MemberForList> = {};
   121          inviteOptions.personalDetails.forEach((detail) => {
   122              if (!detail.login) {
   123                  return;
   124              }
   125
   126              detailsMap[detail.login] = OptionsListUtils.formatMemberForList(detail);
   127          });
   128
   129          const newSelectedOptions: MemberForList[] = [];
   130          if (firstRenderRef.current) {
   131              // We only want to add the saved selected user on first render
   132              firstRenderRef.current = false;
   133              Object.keys(invitedEmailsToAccountIDsDraft ?? {}).forEach((login) => {
   134                  if (!(login in detailsMap)) {
   135                      return;
   136                  }
   137                  newSelectedOptions.push({...detailsMap[login], isSelected: true});
   138              });
   139          }
   140          selectedOptions.forEach((option) => {
   141              newSelectedOptions.push(option.login && option.login in detailsMap ? {...detailsMap[option.login], isSelected: true} : option);
   142          });
   143
   144          const userToInvite = inviteOptions.userToInvite;
   145
   146          // Only add the user to the invites list if it is valid
   147          if (typeof userToInvite?.accountID === 'number') {
   148              newUsersToInviteDict[userToInvite.accountID] = userToInvite;
   149          }
   150
   151          // Add all personal details to the new dict
   152          inviteOptions.personalDetails.forEach((details) => {
   153              if (typeof details.accountID !== 'number') {
   154                  return;
   155              }
   156              newPersonalDetailsDict[details.accountID] = details;
   157          });
   158
   159          // Add all selected options to the new dict
   160          newSelectedOptions.forEach((option) => {
   161              if (typeof option.accountID !== 'number') {
   162                  return;
   163              }
   164              newSelectedOptionsDict[option.accountID] = option;
   165          });
   166
   167          // Strip out dictionary keys and update arrays
   168          setUsersToInvite(Object.values(newUsersToInviteDict));
   169          setPersonalDetails(Object.values(newPersonalDetailsDict));
   170          setSelectedOptions(Object.values(newSelectedOptionsDict));
   171
   172          // eslint-disable-next-line react-compiler/react-compiler, react-hooks/exhaustive-deps -- we don't want to recalculate when selectedOptions change
   173      }, [options.personalDetails, policy?.employeeList, betas, debouncedSearchTerm, excludedUsers, areOptionsInitialized, inviteOptions.personalDetails, inviteOptions.userToInvite]);
   174
   175      const sections: MembersSection[] = useMemo(() => {
   176          const sectionsArr: MembersSection[] = [];
   177
   178          if (!areOptionsInitialized) {
   179              return [];
   180          }
   181
   182          // Filter all options that is a part of the search term or in the personal details
   183          let filterSelectedOptions = selectedOptions;
   184          if (debouncedSearchTerm !== '') {
   185              filterSelectedOptions = selectedOptions.filter((option) => {
   186                  const accountID = option.accountID;
   187                  const isOptionInPersonalDetails = Object.values(personalDetails).some((personalDetail) => personalDetail.accountID === accountID);
   188
   189                  const searchValue = OptionsListUtils.getSearchValueForPhoneOrEmail(debouncedSearchTerm);
   190
   191                  const isPartOfSearchTerm = !!option.text?.toLowerCase().includes(searchValue) || !!option.login?.toLowerCase().includes(searchValue);
   192                  return isPartOfSearchTerm || isOptionInPersonalDetails;
   193              });
   194          }
   195
   196          sectionsArr.push({
   197              title: undefined,
   198              data: filterSelectedOptions,
   199              shouldShow: true,
   200          });
   201
   202          // Filtering out selected users from the search results
   203          const selectedLogins = selectedOptions.map(({login}) => login);
   204          const personalDetailsWithoutSelected = Object.values(personalDetails).filter(({login}) => !selectedLogins.some((selectedLogin) => selectedLogin === login));
   205          const personalDetailsFormatted = personalDetailsWithoutSelected.map((item) => OptionsListUtils.formatMemberForList(item));
   206
   207          sectionsArr.push({
   208              title: translate('common.contacts'),
   209              data: personalDetailsFormatted,
   210              shouldShow: !isEmptyObject(personalDetailsFormatted),
   211          });
   212
   213          Object.values(usersToInvite).forEach((userToInvite) => {
   214              const hasUnselectedUserToInvite = !selectedLogins.some((selectedLogin) => selectedLogin === userToInvite.login);
   215
   216              if (hasUnselectedUserToInvite) {
   217                  sectionsArr.push({
   218                      title: undefined,
   219                      data: [OptionsListUtils.formatMemberForList(userToInvite)],
   220                      shouldShow: true,
   221                  });
   222              }
   223          });
   224
   225          return sectionsArr;
   226      }, [areOptionsInitialized, selectedOptions, debouncedSearchTerm, personalDetails, translate, usersToInvite]);
   227
   228      const toggleOption = (option: MemberForList) => {
   229          Policy.clearErrors(route.params.policyID);
   230
   231          const isOptionInList = selectedOptions.some((selectedOption) => selectedOption.login === option.login);
   232
   233          let newSelectedOptions: MemberForList[];
   234          if (isOptionInList) {
   235              newSelectedOptions = selectedOptions.filter((selectedOption) => selectedOption.login !== option.login);
   236          } else {
   237              newSelectedOptions = [...selectedOptions, {...option, isSelected: true}];
   238          }
   239
   240          setSelectedOptions(newSelectedOptions);
   241      };
   242
   243      const inviteUser = useCallback(() => {
   244          const errors: Errors = {};
   245          if (selectedOptions.length <= 0) {
   246              errors.noUserSelected = 'true';
   247          }
   248
   249          Policy.setWorkspaceErrors(route.params.policyID, errors);
   250          const isValid = isEmptyObject(errors);
   251
   252          if (!isValid) {
   253              return;
   254          }
   255          HttpUtils.cancelPendingRequests(READ_COMMANDS.SEARCH_FOR_REPORTS);
   256
   257          const invitedEmailsToAccountIDs: InvitedEmailsToAccountIDs = {};
   258          selectedOptions.forEach((option) => {
   259              const login = option.login ?? '';
   260              const accountID = option.accountID ?? '-1';
   261              if (!login.toLowerCase().trim() || !accountID) {
   262                  return;
   263              }
   264              invitedEmailsToAccountIDs[login] = Number(accountID);
   265          });
   266          Member.setWorkspaceInviteMembersDraft(route.params.policyID, invitedEmailsToAccountIDs);
   267          Navigation.navigate(ROUTES.WORKSPACE_INVITE_MESSAGE.getRoute(route.params.policyID));
   268      }, [route.params.policyID, selectedOptions]);
   269
   270      const [policyName, shouldShowAlertPrompt] = useMemo(() => [policy?.name ?? '', !isEmptyObject(policy?.errors) || !!policy?.alertMessage], [policy]);
   271
   272      const headerMessage = useMemo(() => {
   273          const searchValue = debouncedSearchTerm.trim().toLowerCase();
   274          if (usersToInvite.length === 0 && CONST.EXPENSIFY_EMAILS.some((email) => email === searchValue)) {
   275              return translate('messages.errorMessageInvalidEmail');
   276          }
   277          if (
   278              usersToInvite.length === 0 &&
   279              excludedUsers.includes(
   280                  PhoneNumber.parsePhoneNumber(LoginUtils.appendCountryCode(searchValue)).possible
   281                      ? PhoneNumber.addSMSDomainIfPhoneNumber(LoginUtils.appendCountryCode(searchValue))
   282                      : searchValue,
   283              )
   284          ) {
   285              return translate('messages.userIsAlreadyMember', {login: searchValue, name: policyName});
   286          }
   287          return OptionsListUtils.getHeaderMessage(personalDetails.length !== 0, usersToInvite.length > 0, searchValue);
   288      }, [excludedUsers, translate, debouncedSearchTerm, policyName, usersToInvite, personalDetails.length]);
   289
   290      const footerContent = useMemo(
   291          () => (
   292              <FormAlertWithSubmitButton
   293                  isDisabled={!selectedOptions.length}
   294                  isAlertVisible={shouldShowAlertPrompt}
   295                  buttonText={translate('common.next')}
   296                  onSubmit={inviteUser}
   297                  message={policy?.alertMessage ?? ''}
   298                  containerStyles={[styles.flexReset, styles.flexGrow0, styles.flexShrink0, styles.flexBasisAuto]}
   299                  enabledWhenOffline
   300              />
   301          ),
   302          [inviteUser, policy?.alertMessage, selectedOptions.length, shouldShowAlertPrompt, styles, translate],
   303      );
   304
   305      useEffect(() => {
   306          ReportActions.searchInServer(debouncedSearchTerm);
   307      }, [debouncedSearchTerm]);
   308
   309      return (
   310          <AccessOrNotFoundWrapper
   311              policyID={route.params.policyID}
   312              accessVariants={[CONST.POLICY.ACCESS_VARIANTS.ADMIN]}
   313              fullPageNotFoundViewProps={{subtitleKey: isEmptyObject(policy) ? undefined : 'workspace.common.notAuthorized', onLinkPress: PolicyUtils.goBackFromInvalidPolicy}}
   314          >
   315              <ScreenWrapper
   316                  shouldEnableMaxHeight
   317                  shouldUseCachedViewportHeight
   318                  testID={WorkspaceInvitePage.displayName}
   319                  includeSafeAreaPaddingBottom={false}
   320                  onEntryTransitionEnd={() => setDidScreenTransitionEnd(true)}
   321              >
   322                  <HeaderWithBackButton
   323                      title={translate('workspace.invite.invitePeople')}
   324                      subtitle={policyName}
   325                      shouldShowGetAssistanceButton
   326                      guidesCallTaskID={CONST.GUIDES_CALL_TASK_IDS.WORKSPACE_MEMBERS}
   327                      onBackButtonPress={() => {
   328                          Policy.clearErrors(route.params.policyID);
   329                          Navigation.goBack();
   330                      }}
   331                  />
   332                  <SelectionList
   333                      canSelectMultiple
   334                      sections={sections}
   335                      ListItem={InviteMemberListItem}
   336                      textInputLabel={translate('selectionList.nameEmailOrPhoneNumber')}
   337                      textInputValue={searchTerm}
   338                      onChangeText={(value) => {
   339                          setSearchTerm(value);
   340                      }}
   341                      headerMessage={headerMessage}
   342                      onSelectRow={toggleOption}
   343                      onConfirm={inviteUser}
   344                      showScrollIndicator
   345                      showLoadingPlaceholder={!areOptionsInitialized || !didScreenTransitionEnd}
   346                      shouldPreventDefaultFocusOnSelectRow={!DeviceCapabilities.canUseTouchScreen()}
   347                      footerContent={footerContent}
   348                      isLoadingNewOptions={!!isSearchingForReports}
   349                  />
   350              </ScreenWrapper>
   351          </AccessOrNotFoundWrapper>
   352      );
   353  }
   354
   355  WorkspaceInvitePage.displayName = 'WorkspaceInvitePage';
   356
   357  export default withNavigationTransitionEnd(
   358      withPolicyAndFullscreenLoading(
   359          withOnyx<WorkspaceInvitePageProps, WorkspaceInvitePageOnyxProps>({
   360              betas: {
   361                  key: ONYXKEYS.BETAS,
   362              },
   363              invitedEmailsToAccountIDsDraft: {
   364                  key: ({route}) => `${ONYXKEYS.COLLECTION.WORKSPACE_INVITE_MEMBERS_DRAFT}${route.params.policyID.toString()}`,
   365              },
   366          })(WorkspaceInvitePage),
   367      ),
   368  );

1  import {useFocusEffect, useIsFocused} from '@react-navigation/native';
     2  import isEmpty from 'lodash/isEmpty';
     3  import type {ForwardedRef} from 'react';
     4  import lodashGet from 'lodash/get';
     5  import React, {forwardRef, useCallback, useEffect, useImperativeHandle, useMemo, useRef, useState} from 'react';
     6  import type {LayoutChangeEvent, SectionList as RNSectionList, TextInput as RNTextInput, SectionListData, SectionListRenderItemInfo} from 'react-native';
     7  import {View} from 'react-native';
     8  import Button from '@components/Button';
     9  import Checkbox from '@components/Checkbox';
    10  import FixedFooter from '@components/FixedFooter';
    11  import OptionsListSkeletonView from '@components/OptionsListSkeletonView';
    12  import {PressableWithFeedback} from '@components/Pressable';
    13  import SafeAreaConsumer from '@components/SafeAreaConsumer';
    14  import SectionList from '@components/SectionList';
    15  import ShowMoreButton from '@components/ShowMoreButton';
    16  import Text from '@components/Text';
    17  import TextInput from '@components/TextInput';
    18  import useActiveElementRole from '@hooks/useActiveElementRole';
    19  import useArrowKeyFocusManager from '@hooks/useArrowKeyFocusManager';
    20  import useKeyboardShortcut from '@hooks/useKeyboardShortcut';
    21  import useKeyboardState from '@hooks/useKeyboardState';
    22  import useLocalize from '@hooks/useLocalize';
    23  import usePrevious from '@hooks/usePrevious';
    24  import useSingleExecution from '@hooks/useSingleExecution';
    25  import useThemeStyles from '@hooks/useThemeStyles';
    26  import getSectionsWithIndexOffset from '@libs/getSectionsWithIndexOffset';
    27  import Log from '@libs/Log';
    28  import * as SearchUtils from '@libs/SearchUtils';
    29  import variables from '@styles/variables';
    30  import CONST from '@src/CONST';
    31  import {isEmptyObject} from '@src/types/utils/EmptyObject';
    32  import arraysEqual from '@src/utils/arraysEqual';
    33  import type {BaseSelectionListProps, ButtonOrCheckBoxRoles, FlattenedSectionsReturn, ListItem, SectionListDataType, SectionWithIndexOffset, SelectionListHandle} from './types';
    34
    35  const getDefaultItemHeight = () => variables.optionRowHeight;
    36
    37  function BaseSelectionList<TItem extends ListItem>(
    38      {
    39          sections,
    40          ListItem,
    41          shouldUseUserSkeletonView,
    42          canSelectMultiple = false,
    43          onSelectRow,
    44          shouldSingleExecuteRowSelect = false,
    45          onCheckboxPress,
    46          onSelectAll,
    47          onDismissError,
    48          getItemHeight = getDefaultItemHeight,
    49          textInputLabel = '',
    50          textInputPlaceholder = '',
    51          textInputValue = '',
    52          textInputHint,
    53          textInputMaxLength,
    54          inputMode = CONST.INPUT_MODE.TEXT,
    55          onChangeText,
    56          initiallyFocusedOptionKey = '',
    57          onScroll,
    58          onScrollBeginDrag,
    59          headerMessage = '',
    60          confirmButtonText = '',
    61          onConfirm,
    62          headerContent,
    63          footerContent,
    64          listFooterContent,
    65          listEmptyContent,
    66          showScrollIndicator = true,
    67          showLoadingPlaceholder = false,
    68          showConfirmButton = false,
    69          shouldPreventDefaultFocusOnSelectRow = false,
    70          containerStyle,
    71          sectionListStyle,
    72          disableKeyboardShortcuts = false,
    73          children,
    74          shouldStopPropagation = false,
    75          shouldPreventDefault = true,
    76          shouldShowTooltips = true,
    77          shouldUseDynamicMaxToRenderPerBatch = false,
    78          rightHandSideComponent,
    79          isLoadingNewOptions = false,
    80          onLayout,
    81          customListHeader,
    82          customListHeaderHeight = 0,
    83          listHeaderWrapperStyle,
    84          isRowMultilineSupported = false,
    85          isAlternateTextMultilineSupported = false,
    86          alternateTextNumberOfLines = 2,
    87          textInputRef,
    88          headerMessageStyle,
    89          shouldHideListOnInitialRender = true,
    90          textInputIconLeft,
    91          sectionTitleStyles,
    92          textInputAutoFocus = true,
    93          shouldTextInputInterceptSwipe = false,
    94          listHeaderContent,
    95          onEndReached = () => {},
    96          onEndReachedThreshold,
    97          windowSize = 5,
    98          updateCellsBatchingPeriod = 50,
    99          removeClippedSubviews = true,
   100          shouldDelayFocus = true,
   101          shouldUpdateFocusedIndex = false,
   102          onLongPressRow,
   103          shouldShowTextInput = !!textInputLabel || !!textInputIconLeft,
   104          shouldShowListEmptyContent = true,
   105      }: BaseSelectionListProps<TItem>,
   106      ref: ForwardedRef<SelectionListHandle>,
   107  ) {
   108      const styles = useThemeStyles();
   109      const {translate} = useLocalize();
   110      const listRef = useRef<RNSectionList<TItem, SectionWithIndexOffset<TItem>>>(null);
   111      const innerTextInputRef = useRef<RNTextInput | null>(null);
   112      const focusTimeoutRef = useRef<NodeJS.Timeout | null>(null);
   113      const shouldShowSelectAll = !!onSelectAll;
   114      const activeElementRole = useActiveElementRole();
   115      const isFocused = useIsFocused();
   116      const [maxToRenderPerBatch, setMaxToRenderPerBatch] = useState(shouldUseDynamicMaxToRenderPerBatch ? 0 : CONST.MAX_TO_RENDER_PER_BATCH.DEFAULT);
   117      const [isInitialSectionListRender, setIsInitialSectionListRender] = useState(true);
   118      const {isKeyboardShown} = useKeyboardState();
   119      const [itemsToHighlight, setItemsToHighlight] = useState<Set<string> | null>(null);
   120      const itemFocusTimeoutRef = useRef<NodeJS.Timeout | null>(null);
   121      const [currentPage, setCurrentPage] = useState(1);
   122      const isTextInputFocusedRef = useRef<boolean>(false);
   123      const {singleExecution} = useSingleExecution();
   124
   125      const incrementPage = () => setCurrentPage((prev) => prev + 1);
   126
   127      /**
   128       * Iterates through the sections and items inside each section, and builds 4 arrays along the way:
   129       * - `allOptions`: Contains all the items in the list, flattened, regardless of section
   130       * - `disabledOptionsIndexes`: Contains the indexes of all the unselectable and disabled items in the list
   131       * - `disabledArrowKeyOptionsIndexes`: Contains the indexes of item that is not navigatable by the arrow key. The list is separated from disabledOptionsIndexes because unselectable item is still navigatable by the arrow key.
   132       * - `itemLayouts`: Contains the layout information for each item, header and footer in the list,
   133       * so we can calculate the position of any given item when scrolling programmatically
   134       */
   135      const flattenedSections = useMemo<FlattenedSectionsReturn<TItem>>(() => {
   136          const allOptions: TItem[] = [];
   137
   138          const disabledOptionsIndexes: number[] = [];
   139          const disabledArrowKeyOptionsIndexes: number[] = [];
   140          let disabledIndex = 0;
   141
   142          // need to account that the list might have some extra content above it
   143          let offset = customListHeader ? customListHeaderHeight : 0;
   144          const itemLayouts = [{length: 0, offset}];
   145
   146          const selectedOptions: TItem[] = [];
   147
   148          sections.forEach((section, sectionIndex) => {
   149              const sectionHeaderHeight = variables.optionsListSectionHeaderHeight;
   150              itemLayouts.push({length: sectionHeaderHeight, offset});
   151              offset += sectionHeaderHeight;
   152
   153              section.data?.forEach((item, optionIndex) => {
   154                  // Add item to the general flattened array
   155                  allOptions.push({
   156                      ...item,
   157                      sectionIndex,
   158                      index: optionIndex,
   159                  });
   160
   161                  // If disabled, add to the disabled indexes array
   162                  const isItemDisabled = !!section.isDisabled || (item.isDisabled && !item.isSelected);
   163                  // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing
   164                  if (isItemDisabled || item.isDisabledCheckbox) {
   165                      disabledOptionsIndexes.push(disabledIndex);
   166                      if (isItemDisabled) {
   167                          disabledArrowKeyOptionsIndexes.push(disabledIndex);
   168                      }
   169                  }
   170                  disabledIndex += 1;
   171
   172                  // Account for the height of the item in getItemLayout
   173                  const fullItemHeight = getItemHeight(item);
   174                  itemLayouts.push({length: fullItemHeight, offset});
   175                  offset += fullItemHeight;
   176
   177                  if (item.isSelected && !selectedOptions.find((option) => option.keyForList === item.keyForList)) {
   178                      selectedOptions.push(item);
   179                  }
   180              });
   181
   182              // We're not rendering any section footer, but we need to push to the array
   183              // because React Native accounts for it in getItemLayout
   184              itemLayouts.push({length: 0, offset});
